            Q('p2', L('Perché il software di Private Cloud Compute è pubblicato?', 'Why is Private Cloud Compute’s software published?'), [L('Perché ricercatori indipendenti possano verificarlo', 'So independent researchers can verify it'), L('Per venderlo', 'To sell it'), L('Per errore', 'By mistake'), L('Non è pubblicato', 'It is not published')], 0, L('Trasparenza verificabile.', 'Verifiable transparency.')),
            Q('p3', L('Che cosa succede prima di inviare una richiesta a ChatGPT?', 'What happens before a request is sent to ChatGPT?'), [L('Il dispositivo chiede conferma', 'The device asks for confirmation'), L('Niente, parte da sola', 'Nothing, it goes by itself'), L('Si riavvia il telefono', 'The phone restarts'), L('Si paga', 'You pay')], 0, L('E si può disattivare.', 'And it can be turned off.')),
        ], task('text', L('Scrivi due righe con `-` che spieghino come Apple protegge la privacy: una sul **dispositivo** e una su **Private Cloud Compute**.', 'Write two lines with `-` explaining how Apple protects privacy: one about the **device** and one about **Private Cloud Compute**.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due righe', 'Two lines')), re('dispositiv|device', L('Il dispositivo', 'The device')), re('Private Cloud Compute', L('Private Cloud Compute', 'Private Cloud Compute'))], '', "- molte richieste sono elaborate direttamente sul dispositivo\n- con Private Cloud Compute i dati servono solo per la richiesta e non vengono conservati"), [
            dMatch(pMatch(), [[L('Sul dispositivo', 'On device'), L('I dati non escono', 'Data does not leave')], ['Private Cloud Compute', L('Server Apple senza conservazione', 'Apple servers without retention')], [L('Software pubblicato', 'Published software'), L('Verificabile da esperti', 'Verifiable by experts')], [L('Conferma per ChatGPT', 'ChatGPT confirmation'), L('Tu decidi ogni volta', 'You decide each time')]], L('Privacy per progetto.', 'Privacy by design.')),
            dFlash(pFlash(), [[L('L’integrazione con ChatGPT si può disattivare', 'The ChatGPT integration can be turned off'), true], [L('Private Cloud Compute conserva tutte le richieste', 'Private Cloud Compute stores all requests'), false], [L('Molte funzioni girano sul dispositivo', 'Many features run on device'), true], [L('Apple vende le richieste agli inserzionisti', 'Apple sells requests to advertisers'), false]], L('Dati protetti.', 'Protected data.')),
        ]),
        lesson('developers', L('Per gli sviluppatori', 'For developers'), [
            P('Con il framework **Foundation Models** le app possono usare il modello di Apple Intelligence **sul dispositivo** direttamente da Swift: niente costi per token, funziona offline e i dati restano sul dispositivo. È adatto a riassunti, estrazione di informazioni, suggerimenti e piccoli testi.', 'With the **Foundation Models** framework apps can use the Apple Intelligence **on-device** model directly from Swift: no per-token costs, it works offline and data stays on the device. It suits summaries, information extraction, suggestions and short texts.'),
            C('import FoundationModels

let sessione = LanguageModelSession(instructions: "Rispondi in italiano, in una frase.")
let risposta = try await sessione.respond(to: "Suggerisci un titolo per una nota sulla spesa.")
print(risposta.content)', 'swift'),
            P('Il modello sul dispositivo è piccolo: ottimo per compiti mirati, non per ragionamenti lunghi o conoscenza enciclopedica. Controlla sempre che sia disponibile sul dispositivo dell’utente e prevedi un comportamento alternativo quando non lo è.', 'The on-device model is small: great for focused tasks, not for long reasoning or encyclopaedic knowledge. Always check it is available on the user’s device and plan a fallback when it is not.'),
        ], [
            Q('d1', L('Quale framework dà accesso al modello sul dispositivo?', 'Which framework gives access to the on-device model?'), ['Foundation Models', 'UIKit', 'CoreData', 'MapKit'], 0, L('Da Swift.', 'From Swift.')),
            Q('d2', L('Qual è un vantaggio del modello sul dispositivo?', 'What is an advantage of the on-device model?'), [L('Funziona offline e senza costi per token', 'Works offline with no per-token costs'), L('È il modello più grande al mondo', 'It is the world’s largest model'), L('Conosce tutte le notizie di oggi', 'It knows all of today’s news'), L('Funziona su Android', 'It works on Android')], 0, L('E i dati restano lì.', 'And data stays there.')),
            Q('d3', L('Per quali compiti è adatto?', 'Which tasks does it suit?'), [L('Compiti mirati come riassunti ed estrazione', 'Focused tasks like summaries and extraction'), L('Ricerche enciclopediche', 'Encyclopaedic research'), L('Ragionamenti lunghissimi', 'Very long reasoning'), L('Generare video', 'Generating video')], 0, L('È un modello piccolo.', 'It is a small model.')),
        ], task('swift', L('Crea una `LanguageModelSession` e chiedi con `respond(to:)` di `"Riassumi in una frase: …"`, poi stampa `content`.', 'Create a `LanguageModelSession` and ask with `respond(to:)` to `"Riassumi in una frase: …"`, then print `content`.'), "import FoundationModels\n", [re('let\s+\w+\s*=\s*LanguageModelSession\s*\(', L('La sessione', 'The session')), re('try\s+await\s+\w+\.respond\s*\(\s*to\s*:\s*"Riassumi in una frase', L('La richiesta', 'The request')), re('print\s*\(\s*\w+\.content\s*\)', L('Stampi la risposta', 'You print the answer'))], '', "let sessione = LanguageModelSession()\nlet risposta = try await sessione.respond(to: \"Riassumi in una frase: oggi riunione alle 10 sul budget.\")\nprint(risposta.content)"), [
            dOrder(pSort(), ['import FoundationModels', 'let sessione = LanguageModelSession()', 'let risposta = try await sessione.respond(to: "Ciao")', 'print(risposta.content)'], L('Importa, crea, chiedi, stampa.', 'Import, create, ask, print.')),
            dMatch(pMatch(), [['FoundationModels', L('Il framework', 'The framework')], ['LanguageModelSession', L('Una conversazione', 'A conversation')], ['respond(to:)', L('Invia la richiesta', 'Sends the request')], [L('Sul dispositivo', 'On device'), L('Offline, niente costi a token', 'Offline, no token costs')]], L('L’AI di Apple nelle tue app.', 'Apple’s AI in your apps.')),
